package com.example.spring_blog.reply;import com.fasterxml.jackson.annotation.JsonIgnoreProperties;import lombok.Builder;import lombok.Data;import lombok.NoArgsConstructor;@JsonIgnoreProperties(ignoreUnknown = true)@NoArgsConstructor@Datapublic class PostDTO {    private Integer userId;    private String body;    private String title;    private Integer id;    @Builder    public PostDTO(Integer userId, String body, String title) {        this.userId = userId;        this.body = body;        this.title = title;    }}